blockquote,
dd,
dl,
figure,
h1,
h2,
h3,
h4,
h5,
h6,
hr,
p,
pre {
  margin: 0;
}
fieldset {
  margin: 0;
  padding: 0;
}
legend {
  padding: 0;
}
menu,
ol,
ul {
  list-style: none;
  margin: 0;
  padding: 0;
}
dialog {
  padding: 0;
}
textarea {
  resize: vertical;
}
input::placeholder,
textarea::placeholder {
  opacity: 1;
  color: #9ca3af;
}
[role="button"],
button {
  cursor: pointer;
}
:disabled {
  cursor: default;
}
audio,
canvas,
embed,
iframe,
img,
object,
svg,
video {
  display: block;
  vertical-align: middle;
}
img,
video {
  max-width: 100%;
  height: auto;
}
[hidden]:where(:not([hidden="until-found"])) {
  display: none;
}
.relative {
  position: relative;
}
.flex {
  display: flex;
}
.inline-flex {
  display: inline-flex;
}
.h-12 {
  height: 3rem;
}
.h-8 {
  height: 2rem;
}
.w-12 {
  width: 3rem;
}
.w-8 {
  width: 2rem;
}
.shrink-0 {
  flex-shrink: 0;
}
.origin-left {
  transform-origin: left;
}
.scale-x-0 {
  --tw-scale-x: 0;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.transform {
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.items-center {
  align-items: center;
}
.justify-start {
  justify-content: flex-start;
}
.gap-2 {
  gap: 0.5rem;
}
.rounded {
  border-radius: 0.25rem;
}
.border-l-2 {
  border-left-width: 2px;
}
.bg-gradient-to-r {
  background-image: linear-gradient(to right, var(--tw-gradient-stops));
}
.from-purple-500 {
  --tw-gradient-from: #a855f7 var(--tw-gradient-from-position);
  --tw-gradient-to: rgb(168 85 247 / 0) var(--tw-gradient-to-position);
  --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to);
}
.via-pink-500 {
  --tw-gradient-to: rgb(236 72 153 / 0) var(--tw-gradient-to-position);
  --tw-gradient-stops: var(--tw-gradient-from),
    #ec4899 var(--tw-gradient-via-position), var(--tw-gradient-to);
}
.to-orange-500 {
  --tw-gradient-to: #f97316 var(--tw-gradient-to-position);
}
.fill-neutral-50 {
  fill: #fafafa;
}
.p-2 {
  padding: 0.5rem;
}
.px-1 {
  padding-left: 0.25rem;
  padding-right: 0.25rem;
}
.pr-6 {
  padding-right: 1.5rem;
}
.font-bold {
  font-weight: 700;
}
.text-neutral-50 {
  --tw-text-opacity: 1;
  color: rgb(250 250 250 / var(--tw-text-opacity, 1));
}
.opacity-0 {
  opacity: 0;
}
.transition-all {
  transition-property: all;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  transition-duration: 150ms;
}
.duration-100 {
  transition-duration: 100ms;
}
.duration-700 {
  transition-duration: 700ms;
}
.before\:absolute::before {
  content: var(--tw-content);
  position: absolute;
}
.before\:left-8::before {
  content: var(--tw-content);
  left: 2rem;
}
.before\:-z-10::before {
  content: var(--tw-content);
  z-index: -10;
}
.before\:h-6::before {
  content: var(--tw-content);
  height: 1.5rem;
}
.before\:w-6::before {
  content: var(--tw-content);
  width: 1.5rem;
}
.before\:rotate-45::before {
  content: var(--tw-content);
  --tw-rotate: 45deg;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.before\:bg-pink-600::before {
  content: var(--tw-content);
  --tw-bg-opacity: 1;
  background-color: rgb(219 39 119 / var(--tw-bg-opacity, 1));
}
.before\:duration-700::before {
  content: var(--tw-content);
  transition-duration: 700ms;
}
.hover\:w-44:hover {
  width: 11rem;
}
.before\:hover\:left-40:hover::before {
  content: var(--tw-content);
  left: 10rem;
}
.before\:hover\:bg-pink-500:hover::before {
  content: var(--tw-content);
  --tw-bg-opacity: 1;
  background-color: rgb(236 72 153 / var(--tw-bg-opacity, 1));
}
.group:hover .group-hover\:scale-x-100 {
  --tw-scale-x: 1;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.group:hover .group-hover\:opacity-100 {
  opacity: 1;
}
.group:hover .group-hover\:delay-500 {
  transition-delay: 500ms;
}
.group:hover .group-hover\:duration-300 {
  transition-duration: 300ms;
}
